49:      * Replaces the whole binding. Called for every constructed media source, so a later response for
50:      * an older video cannot leave its formats resolvable.
51:      *
52:      * @param subtitles  source entries of the request this manifest was built for
53:      * @param candidates text representations of that same manifest
54:      */
55:     public void bind(List<MediaSubtitle> subtitles, List<SubtitleFormatCandidate> candidates) {
56:         clear();
57:         mGeneration++;
58: 
59:         if (subtitles == null || candidates == null) {
60:             return;
61:         }
62: 
63:         Map<String, List<MediaSubtitle>> byUrl = new HashMap<>();
64: 
65:         for (MediaSubtitle subtitle : subtitles) {
66:             if (subtitle == null || subtitle.getBaseUrl() == null) {
67:                 continue;
68:             }
69: 
70:             List<MediaSubtitle> bucket = byUrl.get(subtitle.getBaseUrl());
71: 
72:             if (bucket == null) {
73:                 bucket = new ArrayList<>();
74:                 byUrl.put(subtitle.getBaseUrl(), bucket);
75:             }
76: 
77:             bucket.add(subtitle);
78:         }
79: 
80:         for (SubtitleFormatCandidate candidate : candidates) {
81:             if (candidate == null || candidate.getFormat() == null) {
82:                 continue;
83:             }
84: 
85:             List<MediaSubtitle> matches = candidate.getBaseUrl() != null ? byUrl.get(candidate.getBaseUrl()) : null;
86: 
87:             if (matches == null || matches.size() != 1) {
88:                 // 0 matches: the source list and the manifest disagree.
89:                 // 2+ matches: the URL cannot identify one source. Never pick the first candidate.
90:                 mUnresolvedByFormat.put(candidate.getFormat(), matches != null && matches.size() > 1);
91:                 mRejectedCount++;
92:                 continue;
93:             }
94: 
95:             mSourceByFormat.put(candidate.getFormat(), SelectedSubtitleSource.from(matches.get(0), candidate.getBaseUrl(), mGeneration));
96:             mBoundCount++;
97:         }
98:     }
