100:     /**
101:      * Resolves the subtitle source of an actually selected track.
102:      *
103:      * @param track the selected subtitle track, or null/empty when subtitles are off
104:      * @return the bound source, or null with {@link #getStatus()} explaining the refusal
105:      */
106:     public SelectedSubtitleSource resolve(MediaTrack track) {
107:         if (track == null || track.format == null || track.isEmpty()) {
108:             mSelectedSource = null;
109:             mStatus = Status.NOT_SELECTED;
110:             return null;
111:         }
112: 
113:         return resolve(track.format);
