116:     /** Resolves a selected subtitle {@link Format} by identity. */
117:     public SelectedSubtitleSource resolve(Format format) {
118:         if (format == null) {
119:             mSelectedSource = null;
120:             mStatus = Status.NOT_SELECTED;
121:             return null;
122:         }
123: 
124:         SelectedSubtitleSource source = mSourceByFormat.get(format);
125: 
126:         if (source != null) {
127:             mSelectedSource = source;
128:             mStatus = Status.BOUND;
129:             return source;
130:         }
131: 
132:         mSelectedSource = null;
133: 
134:         Boolean ambiguous = mUnresolvedByFormat.get(format);
135:         mStatus = ambiguous == null ? (mBoundCount == 0 && mGeneration == 0 ? Status.UNBOUND : Status.SOURCE_UNKNOWN)
136:                 : (ambiguous ? Status.SOURCE_AMBIGUOUS : Status.SOURCE_UNKNOWN);
137: 
138:         return null;
139:     }
