63:      * @param cancelled checked before the read and repeatedly by the reader; a cancelled fetch
64:      *                  returns {@link SubtitleSnapshotReader.Status#CANCELLED}
65:      */
66:     public Result fetch(SelectedSubtitleSource source, Format format, long mediaEndUs, SubtitleSnapshotReader.Cancellation cancelled) {
67:         if (source == null || mReader == null) {
68:             return new Result(SubtitleSnapshotReader.Status.NO_SOURCE, null);
69:         }
70: 
71:         if (isCancelled(cancelled)) {
72:             return new Result(SubtitleSnapshotReader.Status.CANCELLED, null);
73:         }
74: 
75:         InputStream payload = null;
76: 
77:         try {
78:             payload = mPayloadFactory != null ? mPayloadFactory.open(source) : null;
79: 
80:             if (isCancelled(cancelled)) {
81:                 return new Result(SubtitleSnapshotReader.Status.CANCELLED, null);
82:             }
83: 
84:             SubtitleSnapshotReader.Snapshot snapshot =
85:                     mReader.read(format, payload, mediaEndUs, () -> isCancelled(cancelled));
86: 
87:             return new Result(snapshot.getStatus(), snapshot.getTimeline());
88:         } catch (RuntimeException e) {
89:             return new Result(SubtitleSnapshotReader.Status.IO_FAILED, null);
90:         } finally {
91:             if (payload != null) {
92:                 try {
93:                     payload.close();
94:                 } catch (IOException ignored) {
95:                     // The result already exists; a failing close changes nothing.
96:                 }
97:             }
98:         }
99:     }
